from decimal import Decimal

def compound(rate: Decimal, n: int, mode: str = "annual") -> Decimal:
    r = Decimal(str(rate))
    one = Decimal(1)
    if mode == "annual":
        return (one + r) ** n
    elif mode == "semi-annual":
        return (one + r / 2) ** (2 * n)
    elif mode == "continuous":
        return (r * Decimal(str(n))).exp()
    else:
        raise ValueError(f"unknown mode: {mode}")

from decimal import Decimal

def discount_factor(rate: Decimal, t: float, mode: str = "annual") -> Decimal:
    r = Decimal(str(rate))
    one = Decimal(1)
    n = Decimal(str(t))
    if mode == "annual":
        return (one + r) ** (-n)
    elif mode == "semi-annual":
        return (one + r / 2) ** (-2 * n)
    elif mode == "continuous":
        return (-r * n).exp()
    else:
        raise ValueError(f"unknown mode: {mode}")

def present_value_of_flow(amount: Decimal, t: float, rate: Decimal, mode: str = "annual") -> Decimal:
    return amount * discount_factor(rate, t, mode)

from decimal import Decimal, ROUND_HALF_UP

def present_value(rate: float, nper: int, pmt: float, fv: float = 0.0, when: str = "end", *, ndigits=None) -> Decimal:
    r = Decimal(str(rate))
    n = Decimal(str(nper))
    p = Decimal(str(pmt))
    fv_dec = Decimal(str(fv))
    one = Decimal(1)
    if r == 0:
        pv = p * n + fv_dec
    else:
        factor = (one + r) ** n
        if when == "begin":
            pv = p * (one + r) * (one - (one + r) ** (-n)) / r + fv_dec / factor
        else:
            pv = p * (one - (one + r) ** (-n)) / r + fv_dec / factor
    if ndigits is not None:
        pv = pv.quantize(Decimal(10) ** (-ndigits), rounding=ROUND_HALF_UP)
    return pv

