from decimal import Decimal, ROUND_HALF_UP

def amortization_schedule(principal: float, annual_rate: float, years: float, payments_per_year: int = 12, *, ndigits=None) -> list[dict[str, Decimal]]:
    n = int(years * payments_per_year)
    r = Decimal(str(annual_rate)) / Decimal(str(payments_per_year))
    pv = Decimal(str(principal))
    one = Decimal(1)
    if r == 0:
        pmt = pv / Decimal(str(n))
    else:
        pmt = pv * r * (one + r) ** n / ((one + r) ** n - one)
    schedule = []
    balance = pv
    for period in range(1, n + 1):
        interest = balance * r
        principal_part = pmt - interest
        balance -= principal_part
        if period == n:
            principal_part += balance
            interest = Decimal(0)
            pmt = principal_part
            balance = Decimal(0)
        if balance < 0:
            balance = Decimal(0)
        entry = {"period": Decimal(str(period)), "payment": pmt, "interest": interest, "principal": principal_part, "balance": balance}
        if ndigits is not None:
            entry = {k: v.quantize(Decimal(10) ** (-ndigits), rounding=ROUND_HALF_UP) for k, v in entry.items()}
        schedule.append(entry)
    return schedule

from decimal import Decimal, ROUND_HALF_UP

def historical_var(returns: list[float], confidence_level: float = 0.95, *, ndigits=None) -> Decimal:
    if not returns:
        raise ValueError("Returns list is empty")
    sorted_returns = sorted(returns)
    index = int((1 - confidence_level) * len(sorted_returns))
    if index >= len(sorted_returns):
        index = len(sorted_returns) - 1
    result = abs(Decimal(str(sorted_returns[index])))
    if ndigits is not None:
        result = result.quantize(Decimal(10) ** (-ndigits), rounding=ROUND_HALF_UP)
    return result

