from decimal import Decimal

def log_returns(prices: list[float]) -> list[Decimal]:
    if len(prices) < 2:
        raise ValueError("Need at least 2 prices")
    results = []
    for i in range(1, len(prices)):
        r = Decimal(str(prices[i])) / Decimal(str(prices[i - 1]))
        results.append(r.ln())
    return results

