from finpy.core.types import Cashflow
from finpy.core.errors import SchemaValidationError

def validate_cashflow(data: dict) -> Cashflow:
    if "amount" not in data or "t" not in data:
        raise SchemaValidationError("cashflow must have 'amount' and 't' fields")
    try:
        return Cashflow(amount=Decimal(str(data["amount"])), t=float(data["t"]))
    except (ValueError, TypeError) as e:
        raise SchemaValidationError(str(e))

def dump_cashflow(cf: Cashflow) -> dict:
    return {"amount": str(cf.amount), "t": cf.t}

def load_cashflow(data: dict) -> Cashflow:
    return validate_cashflow(data)

from finpy.core.errors import MigrationError
SCHEMA_VERSION = 1
DESCRIPTION = "Initial schema"
def upgrade(payload: dict) -> dict:
    if "value" not in payload:
        raise MigrationError("payload missing 'value'")
    return {"version": 1, "data": {"value": str(payload["value"]), "label": payload.get("label", "")}}
def downgrade(payload: dict) -> dict:
    if not isinstance(payload, dict) or "data" not in payload:
        raise MigrationError("invalid schema-1 payload")
    return {"value": payload["data"]["value"], "label": payload["data"]["label"]}

from decimal import Decimal

def approx_decimal(value, expected, places=4):
    return abs(value - Decimal(str(expected))) < Decimal(10) ** (-places)
